#!/usr/bin/env python3
"""Turn-budget control-flow guard for the AppWorld harness.

This is a stateless, fail-open guard for the Bash tool. It reads the current
hook payload from stdin and emits at most one JSON decision. It never writes
state and never retries, so it is bounded by construction.

It is configured for both PreToolUse and PostToolUse on Bash:

PreToolUse
  * commands containing the configured completion marker are always allowed;
  * before the hard limit, Bash is allowed silently;
  * at or beyond the hard limit, non-completion Bash is denied with a short,
    actionable reason telling the model to submit.

PostToolUse
  * between the soft and hard limits, emits a compact budget-status
    additionalContext so the model sees how many tool uses remain before the
    hard stop.

The tool-use count is read by streaming the current session transcript. If the
transcript cannot be located or read, the guard fails open and never blocks a
legitimate tool call.
"""

import json
import os
import re
import sys

TOOL_USE_TYPE_RE = re.compile(
    r'"type"\s*:\s*"(tool_use|ToolUseBlock|server_tool_use)"'
)
MAX_TRANSCRIPT_BYTES = 128 * 1024 * 1024


def parse_args(argv):
    """Return (completion_marker, soft_limit, hard_limit) from CLI args."""
    marker = "complete_task"
    soft = 20
    hard = 28
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--completion-marker" and i + 1 < len(argv):
            marker = argv[i + 1]
            i += 2
        elif arg == "--soft-limit" and i + 1 < len(argv):
            try:
                soft = int(argv[i + 1])
            except ValueError:
                pass
            i += 2
        elif arg == "--hard-limit" and i + 1 < len(argv):
            try:
                hard = int(argv[i + 1])
            except ValueError:
                pass
            i += 2
        else:
            i += 1
    return marker, soft, hard


def count_tool_uses(transcript_path):
    """Return the number of tool uses in the current session transcript.

    The count is a streaming regex over JSONL transcript lines so it does not
    need to parse potentially large tool outputs as JSON. Returns ``None`` when
    the transcript cannot be read, so the guard fails open.
    """
    if not transcript_path:
        return None

    try:
        size = os.path.getsize(transcript_path)
    except OSError:
        return None

    if size <= 0 or size > MAX_TRANSCRIPT_BYTES:
        return None

    count = 0
    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                count += len(TOOL_USE_TYPE_RE.findall(line))
        return count
    except OSError:
        return None


def extract_command(tool_input):
    """Best-effort extraction of the Bash command from the hook payload."""
    if not isinstance(tool_input, dict):
        return ""
    command = tool_input.get("command") or ""
    if isinstance(command, list):
        command = " ".join(str(part) for part in command)
    return str(command)


def extract_cwd(payload):
    """Return the most specific working directory available in the payload."""
    cwd = payload.get("cwd") or ""
    if cwd:
        return cwd

    tool_input = payload.get("tool_input") or {}
    if isinstance(tool_input, dict):
        cwd = tool_input.get("cwd") or tool_input.get("working_directory") or ""
    return cwd


def resolve_transcript_path(payload):
    """Return an absolute transcript path, or '' when it cannot be resolved."""
    transcript_path = payload.get("transcript_path") or payload.get("transcript") or ""
    if not transcript_path:
        return ""

    if os.path.isabs(transcript_path):
        return transcript_path

    cwd = extract_cwd(payload)
    if cwd:
        return os.path.join(cwd, transcript_path)
    return ""


def emit_allow():
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "allow",
            "permissionDecisionReason": "",
        }
    }))
    sys.exit(0)


def emit_deny(reason):
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    }))
    sys.exit(0)


def emit_context(context):
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PostToolUse",
            "additionalContext": context,
        }
    }))
    sys.exit(0)


def main():
    marker, soft, hard = parse_args(sys.argv[1:])

    try:
        payload = json.load(sys.stdin)
    except Exception:
        return 0

    event = payload.get("hook_event_name") or ""
    if event not in ("PreToolUse", "PostToolUse"):
        return 0

    tool_name = payload.get("tool_name") or payload.get("tool") or ""
    if tool_name != "Bash":
        return 0

    command = extract_command(payload.get("tool_input") or {})
    if not command.strip():
        if event == "PreToolUse":
            emit_allow()
        return 0

    used = count_tool_uses(resolve_transcript_path(payload))

    if event == "PreToolUse":
        # The terminal completion call is always allowed.
        if marker and marker in command:
            emit_allow()
            return

        # Fail open if the transcript count is unavailable.
        if used is None:
            emit_allow()
            return

        if used >= hard:
            emit_deny(
                "Turn-budget hard stop: {} tool uses have already been recorded. "
                "Only the task-completion call (`{}`) is allowed now. Submit the "
                "best-supported answer or state immediately; do not start new "
                "probes, inspections, or unrelated actions.".format(used, marker)
            )
            return

        emit_allow()
        return

    # PostToolUse: inject a compact budget status only in the warning band.
    if used is None or (marker and marker in command):
        return 0

    if soft <= used < hard:
        emit_context(
            "Turn-budget status: {} tool uses recorded; the hard stop is at {} "
            "tool uses, after which only the task-completion call (`{}`) is "
            "allowed. If you already have a candidate answer or completed "
            "state, finish now.".format(used, hard, marker)
        )

    return 0


if __name__ == "__main__":
    main()

