#!/usr/bin/env python3
"""Post-Bash verification and readiness reminders for the AppWorld harness.

This is a PostToolUse hook for Bash tool calls. It is stateless and
task-agnostic: it reads only the current hook payload and never writes state.

It emits one JSON object on stdout for the hook runtime to inject into the
model context when the just-finished Bash command either:

1. looks like a state-changing call on a dotted app/API namespace, or
2. produced output that looks like a candidate final answer or a positive
   self-check.

The first case preserves the original mutation-verification reminder. The
second case targets the failure mode where the model has already printed the
answer or a clean self-check but then keeps exploring instead of submitting, or
submits against a self-selected/proxy check rather than the exact graded
predicate.

The patterns are namespace-agnostic and are not tied to AppWorld task IDs,
expected answers, or app-specific constants.
"""

import json
import re
import sys

# Namespace-agnostic: <identifier>.<identifier>.<mutation_verb>...
# This matches `apis.spotify.create_playlist`, `any_app.obj.update_record`, etc.,
# without depending on a specific tool namespace.
MUTATION_RE = re.compile(
    r"(?:^|[^A-Za-z0-9_])"
    r"[A-Za-z_][A-Za-z0-9_]*\."
    r"[A-Za-z_][A-Za-z0-9_]*\."
    r"(?:create_|add_|update_|delete_|remove_|set_|save_|send_|post_|upload_|"
    r"like_|unlike_|comment_|follow_|unfollow_|play_|pause_|clear_|"
    r"transfer_|pay_|request_|accept_|decline_|reset_|change_)"
)

# Signals that the just-finished command printed a candidate answer or a
# self-check that the model might treat as final. These are intentionally
# multi-word/structured so normal docs and list outputs do not trigger them.
READINESS_RES = [
    re.compile(r"SUM\s*="),
    re.compile(r"problem\s+tids?\s*:\s*\[\]", re.IGNORECASE),
    re.compile(r"bad_comment\s+tids?\s*:\s*\[\]", re.IGNORECASE),
    re.compile(r"MISSING\s*:\s*\[\]"),
    re.compile(r"All requirements\s+(?:verified|match|satisfied)", re.IGNORECASE),
    re.compile(r"->\s*True"),
    re.compile(r"\bRESULT\s*:\s*ALL\b", re.IGNORECASE),
    re.compile(r"\bsatisfies\b", re.IGNORECASE),
]

MUTATION_REMINDER = (
    "Post-mutation check: you just ran a state-changing command. Before calling "
    "the task-completion API, re-fetch the affected object(s) and verify every "
    "graded predicate exactly: counts and totals are separate, owner/visibility "
    "fields, current queue/state, and inclusive date or selection bounds. Fix "
    "any mismatch before submitting."
)

READINESS_REMINDER = (
    "Readiness check: this output looks like a candidate final answer or a "
    "positive self-check. If it is the final answer for a question task, submit "
    "it with `apis.supervisor.complete_task(answer=<value>)` next. If it is a "
    "mutation/state task, re-fetch the exact graded object(s) and compare every "
    "required predicate (count, owner/visibility, queue/state, inclusive date "
    "bounds) before calling `complete_task(status='success')`. Do not start new "
    "probes after this point."
)


def _extract_command(tool_input):
    if not isinstance(tool_input, dict):
        return ""
    command = tool_input.get("command") or ""
    if isinstance(command, list):
        command = " ".join(str(part) for part in command)
    return str(command)


def _text_from_block(block):
    """Best-effort extraction of readable text from a tool-result block."""
    if isinstance(block, str):
        return block
    if isinstance(block, dict):
        for key in ("text", "content", "output", "stdout", "stderr"):
            value = block.get(key)
            if value is None:
                continue
            if isinstance(value, str):
                return value
            if isinstance(value, list):
                return "\n".join(_text_from_block(item) for item in value)
            return str(value)
        return ""
    return str(block)


def _extract_response_text(payload):
    """Return the Bash tool output as a string, if the payload contains it."""
    response = payload.get("tool_response")
    if response is None:
        response = payload.get("tool_output") or payload.get("tool_result")

    if response is None:
        return ""
    if isinstance(response, str):
        return response
    if isinstance(response, dict):
        parts = []
        for key in ("stdout", "stderr", "output", "text", "result", "content"):
            value = response.get(key)
            if value is None:
                continue
            if isinstance(value, str):
                parts.append(value)
            elif isinstance(value, list):
                parts.extend(_text_from_block(item) for item in value)
            elif isinstance(value, dict):
                parts.append(_text_from_block(value))
            else:
                parts.append(str(value))
        return "\n".join(parts)
    if isinstance(response, list):
        return "\n".join(_text_from_block(item) for item in response)
    return str(response)


def main() -> int:
    try:
        payload = json.load(sys.stdin)
    except Exception:
        return 0

    event = payload.get("hook_event_name")
    if event is not None and event != "PostToolUse":
        return 0

    tool_name = payload.get("tool_name") or payload.get("tool") or ""
    if tool_name and tool_name != "Bash":
        return 0

    command = _extract_command(payload.get("tool_input") or {})
    if not command.strip():
        return 0

    # Do not nag immediately after the completion call itself.
    if "complete_task" in command:
        return 0

    response_text = _extract_response_text(payload)
    # Keep the regex scan bounded even for very large persisted outputs.
    scan_text = response_text[:20000]

    is_mutation = bool(MUTATION_RE.search(command))
    is_readiness = any(
        pattern.search(scan_text) or pattern.search(command)
        for pattern in READINESS_RES
    )

    if not (is_mutation or is_readiness):
        return 0

    reminders = []
    if is_mutation:
        reminders.append(MUTATION_REMINDER)
    if is_readiness:
        reminders.append(READINESS_REMINDER)

    output = {
        "hookSpecificOutput": {
            "hookEventName": "PostToolUse",
            "additionalContext": " ".join(reminders),
        }
    }
    sys.stdout.write(json.dumps(output))
    return 0


if __name__ == "__main__":
    sys.exit(main())

