#!/usr/bin/env python3
"""AppWorld submission guard for Claude Code hooks.

PreToolUse: block web detours and, near the turn cap, block off-task Bash so the
model calls supervisor.complete_task instead of probing the runtime.
Stop: block stopping unless a supervisor.complete_task call is present in the
transcript.
"""
import json
import os
import sys

OFF_TASK_THRESHOLD = 18
SUCCESS_MARKER = "Marked the active task complete"


def _iter_tool_use_blocks(obj):
    """Yield all ToolUseBlock/tool_use dicts found anywhere in *obj*."""
    if isinstance(obj, dict):
        if obj.get("type") in ("tool_use", "ToolUseBlock"):
            yield obj
        for value in obj.values():
            yield from _iter_tool_use_blocks(value)
    elif isinstance(obj, list):
        for value in obj:
            yield from _iter_tool_use_blocks(value)


def _block_calls_complete_task(block):
    try:
        raw = json.dumps(block.get("input"))
    except Exception:
        raw = str(block.get("input"))
    return "complete_task" in raw.lower()


def _scan_transcript(data):
    """Return (tool_call_count, complete_task_seen) from the transcript."""
    path = data.get("transcript_path") or data.get("transcriptPath") or ""
    if not path or not os.path.exists(path):
        return 0, False

    count = 0
    submitted = False
    valid_lines = 0

    try:
        with open(path, "r", errors="ignore") as handle:
            for line in handle:
                if SUCCESS_MARKER in line:
                    submitted = True
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                valid_lines += 1
                for block in _iter_tool_use_blocks(obj):
                    count += 1
                    if _block_calls_complete_task(block):
                        submitted = True
    except Exception:
        pass

    if valid_lines == 0:
        # Not JSONL; try a single JSON document.
        try:
            with open(path, "r", errors="ignore") as handle:
                obj = json.load(handle)
            if SUCCESS_MARKER in json.dumps(obj):
                submitted = True
            for block in _iter_tool_use_blocks(obj):
                count += 1
                if _block_calls_complete_task(block):
                    submitted = True
        except Exception:
            pass

    return count, submitted


def _block(reason, event):
    out = {"decision": "block", "reason": reason}
    if event == "PreToolUse":
        out["hookSpecificOutput"] = {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    elif event == "Stop":
        out["hookSpecificOutput"] = {
            "hookEventName": "Stop",
            "hookSpecificDecision": "block",
            "reason": reason,
        }
    print(json.dumps(out))
    return 0


def main():
    raw = sys.stdin.read()
    if not raw.strip():
        return 0
    try:
        data = json.loads(raw)
    except Exception:
        return 0
    if not isinstance(data, dict):
        return 0

    event = data.get("hook_event_name") or data.get("hookEventName") or ""
    tool_name = data.get("tool_name") or ""

    if event == "PreToolUse":
        if tool_name in ("WebSearch", "WebFetch"):
            return _block(
                "WebSearch/WebFetch are not useful for AppWorld tasks; use the "
                "apis.* shell bridge and then call supervisor.complete_task.",
                event,
            )
        if tool_name == "Bash":
            tool_input = data.get("tool_input") or {}
            command = ""
            if isinstance(tool_input, dict):
                command = tool_input.get("command") or ""
            prior, _ = _scan_transcript(data)
            if prior >= OFF_TASK_THRESHOLD and command:
                if (
                    "appworld_client.py" not in command
                    and "complete_task" not in command.lower()
                ):
                    return _block(
                        "You are near the 30-turn limit and this shell command "
                        "is not an AppWorld API call. If you have the answer or "
                        "finished state, call apis.supervisor.complete_task(...) "
                        "now. Do not inspect the runtime, packages, other apps, "
                        "or the web.",
                        event,
                    )
        return 0

    if event == "Stop":
        _, submitted = _scan_transcript(data)
        if submitted:
            return 0
        return _block(
            "You have not called apis.supervisor.complete_task(...) yet. Call it "
            "to mark the task complete before stopping.",
            event,
        )

    return 0


if __name__ == "__main__":
    sys.exit(main())

