#!/usr/bin/env python3
"""PreToolUse guard for AppWorld tasks.

Fail-open, allow-by-default guard. It denies only tool calls that cannot change
the graded answer or final state and are known to consume the turn budget:
web access, shell/package/network/filesystem probes, and local cryptographic
brute-forcing. AppWorld bridge calls, local Python that parses persisted tool
results, and supervisor.complete_task are always allowed.
"""

import json
import re
import sys


def emit(decision, reason=""):
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": decision,
            "permissionDecisionReason": reason,
        }
    }))


def allow():
    emit("allow")
    sys.exit(0)


def deny(reason):
    emit("deny", reason)
    sys.exit(0)


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        allow()
        return

    tool_name = data.get("tool_name", "")
    tool_input = data.get("tool_input") or {}
    command = tool_input.get("command", "") if isinstance(tool_input, dict) else str(tool_input)
    low = command.lower()

    if tool_name in ("WebSearch", "WebFetch"):
        deny("Web access does not affect the AppWorld grader and only consumes turns. Use the documented appworld_client APIs and then supervisor.complete_task.")
        return
    if tool_name != "Bash":
        allow()
        return

    # Submission must never be blocked.
    if "supervisor.complete_task" in command:
        allow()
        return

    # Network and package probes.
    if re.search(r'(^|[\s;&|`])(curl|wget|git\s+clone|git\s+ls-remote)(\s|$)', low):
        deny("Network probes cannot affect the AppWorld grader and only consume turns. Use documented appworld_client APIs and then supervisor.complete_task.")
        return
    if re.search(r'(^|[\s;&|`/])pip3?\s+(list|install|download|index|show|uninstall|freeze)(\s|$)', low):
        deny("Package probes cannot affect the AppWorld grader and only consume turns. Use documented appworld_client APIs and then supervisor.complete_task.")
        return
    if re.search(r'(^|[\s;&|`/])python3?\s+-m\s+pip(\s|$)', low):
        deny("Package probes cannot affect the AppWorld grader and only consume turns. Use documented appworld_client APIs and then supervisor.complete_task.")
        return
