#!/usr/bin/env python3
"""Soft turn-budget guard for the AppWorld harness.

This is a PreToolUse hook for Bash tool calls. It is stateless and
task-agnostic: it reads only the current hook payload and the current session
transcript path supplied in that payload. It never writes any state.

When the session is near the hard turn limit (>= SOFT_TOOL_USES tool uses) and
the next Bash command is not the supervisor completion call, it emits one JSON
object on stdout so the hook runtime injects a short reminder into the model
context. This targets the failure mode where the agent already has a candidate
answer or completed state but keeps probing until the turn cap fires.
"""

import json
import os
import re
import sys

SOFT_TOOL_USES = 28
MAX_TRANSCRIPT_BYTES = 128 * 1024 * 1024

# Live Claude Code transcripts use lowercase ``tool_use`` blocks inside
# assistant messages. The saved graded-trajectory format uses ``ToolUseBlock``.
# Count either type marker once per occurrence.
TOOL_USE_TYPE_RE = re.compile(
    r'"type"\s*:\s*"(tool_use|ToolUseBlock|server_tool_use)"'
)

REMINDER_TEMPLATE = (
    "Turn-budget guard: this session has already used at least {used} tool calls "
    "and is near the 30-call limit. If you already have a candidate answer or a "
    "completed final state, make the next tool call "
    "`apis.supervisor.complete_task(...)` and submit. If you still need to verify, "
    "make at most one focused re-fetch of the exact graded object(s), then "
    "complete_task. Do not start any new probe, web lookup, source/package "
    "inspection, or unrelated-app exploration."
)


def _count_tool_uses(transcript_path):
    """Return the number of tool uses in the current session transcript.

    The count is a streaming regex over JSONL transcript lines, so it does not
    need to parse potentially large tool outputs as JSON. Returns ``None`` when
    the transcript cannot be read, so the guard fails open (no reminder) rather
    than interrupting a healthy session.
    """
    if not transcript_path:
        return None

    try:
        size = os.path.getsize(transcript_path)
    except OSError:
        return None

    if size <= 0 or size > MAX_TRANSCRIPT_BYTES:
        return None

    count = 0
    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                count += len(TOOL_USE_TYPE_RE.findall(line))
        return count
    except OSError:
        return None


def _extract_command(tool_input):
    if not isinstance(tool_input, dict):
        return ""
    command = tool_input.get("command") or ""
    if isinstance(command, list):
        command = " ".join(str(part) for part in command)
    return str(command)


def main() -> int:
    try:
        payload = json.load(sys.stdin)
    except Exception:
        return 0

    event = payload.get("hook_event_name")
    if event is not None and event != "PreToolUse":
        return 0

    tool_name = payload.get("tool_name") or ""
    if tool_name != "Bash":
        return 0

    command = _extract_command(payload.get("tool_input") or {})
    if not command.strip():
        return 0

    # Do not nag immediately before the completion call itself.
    if "complete_task" in command:
        return 0

    transcript_path = payload.get("transcript_path") or ""
    if transcript_path and not os.path.isabs(transcript_path):
        cwd = payload.get("cwd") or ""
        if cwd:
            transcript_path = os.path.join(cwd, transcript_path)

    used = _count_tool_uses(transcript_path)
    if used is None or used < SOFT_TOOL_USES:
        return 0

    output = {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "additionalContext": REMINDER_TEMPLATE.format(used=used),
        }
    }
    sys.stdout.write(json.dumps(output))
    return 0


if __name__ == "__main__":
    sys.exit(main())
